const satQuestions = window.LAUNCHPAD_SAT_QUESTIONS || {
 rw:[
  {id:"rw1",skill:"Words in Context",domain:"Craft and Structure",passage:"When the neighborhood garden opened, volunteers expected the new path to be mostly decorative. Instead, it proved ______: visitors used it to reach the garden beds, and gardeners used it to move tools without disturbing the soil.",prompt:"Which choice completes the text with the most logical and precise word?",options:["incidental","practical","fragile","remote"],answer:1,explanation:"“Practical” means useful for a purpose. The details show that people used the path to reach beds and carry tools."},
  {id:"rw2",skill:"Central Ideas and Details",domain:"Information and Ideas",passage:"A team of students tracked shade around their school courtyard at three times of day. The east side was shaded in the morning, while the west side was shaded in late afternoon. They concluded that a single measurement would miss important changes across the day.",prompt:"Which choice best states the main idea of the text?",options:["Courtyard shade patterns change during the day, so repeated observations matter.","Students should avoid working in courtyards during the afternoon.","The east side of the courtyard is always cooler than the west side.","A single measurement is more accurate than several measurements."],answer:0,explanation:"The passage compares shade at multiple times and concludes that one measurement would miss changes. It does not claim one side is always cooler."},
  {id:"rw3",skill:"Transitions",domain:"Expression of Ideas",passage:"Many city trees grow in small sidewalk openings. ______, researchers have found that trees planted in larger soil areas often grow wider canopies.",prompt:"Which choice completes the text with the most logical transition?",options:["For example","By contrast","As a result","In addition"],answer:1,explanation:"The second sentence contrasts trees in small openings with trees in larger soil areas, so “By contrast” is the best transition."},
  {id:"rw4",skill:"Command of Evidence",domain:"Information and Ideas",passage:"A school added two outdoor study tables. In a student poll, 42 of 60 respondents said they used the tables at least once a week.",prompt:"Which finding most directly supports the claim that the tables were used regularly?",options:["The tables are made of recycled plastic.","Most polled students reported using the tables weekly.","The tables are near a garden.","The school has several indoor study spaces."],answer:1,explanation:"The poll directly measures frequency of use, and 42 of 60 respondents reported weekly use."},
  {id:"rw5",skill:"Inferences",domain:"Information and Ideas",passage:"Although Mira had planned to photograph the old bridge at sunrise, she returned in the afternoon after noticing that the river reflected the bridge's iron arches more clearly then.",prompt:"Which statement is best supported by the text?",options:["Mira abandoned the photography project.","Mira adjusted her plan after observing the scene.","The bridge was built in the afternoon.","Sunrise is always a poor time for photography."],answer:1,explanation:"Mira changed when she took the photograph based on what she observed. The text makes no broader claim about sunrise."},
  {id:"rw6",skill:"Text Structure and Purpose",domain:"Craft and Structure",passage:"For decades, maps of the region showed a single broad wetland. A recent survey, however, identified several smaller wetlands separated by seasonal streams. The revised map gives conservation planners a more precise picture of the habitat.",prompt:"What is the main purpose of the text?",options:["To explain why an updated survey changed a map","To argue that streams should be removed","To compare two conservation organizations","To describe how to draw a map by hand"],answer:0,explanation:"The passage contrasts an older map with new survey findings and explains how the updated map is useful."},
  {id:"rw7",skill:"Cross-Text Connections",domain:"Craft and Structure",passage:"Text 1: A town should plant shade trees along its busiest walking routes first. Text 2: New plantings should be concentrated in blocks with the fewest existing trees, even when those blocks have less foot traffic.",prompt:"How would the author of Text 2 most likely respond to Text 1?",options:["By agreeing that foot traffic should be the only priority","By suggesting that current tree coverage should also guide priorities","By arguing that trees cannot provide shade","By recommending that the town stop maintaining trees"],answer:1,explanation:"Text 2 prioritizes blocks with low tree coverage, indicating that equity in existing coverage should shape planting decisions too."},
  {id:"rw8",skill:"Rhetorical Synthesis",domain:"Expression of Ideas",passage:"Student notes: The school garden has 12 raised beds. Biology classes use it to study pollinators. The garden club donates vegetables to a neighborhood pantry.",prompt:"A student wants to emphasize that the garden supports both learning and the community. Which choice best uses the notes?",options:["The school garden contains 12 raised beds.","Biology classes study pollinators in the garden, which also grows vegetables for a neighborhood pantry.","The garden club meets at the school.","Pollinators visit many kinds of gardens."],answer:1,explanation:"This choice combines the learning use and community donation purpose, matching the stated goal."},
  {id:"rw9",skill:"Boundaries",domain:"Standard English Conventions",passage:"The observatory opened its roof for visitors on Friday, the clear sky made several planets easy to see.",prompt:"Which choice best completes the text using standard punctuation?",options:["Friday, the clear sky made","Friday; the clear sky made","Friday the clear sky, made","Friday: and the clear sky made"],answer:1,explanation:"A semicolon correctly joins two independent clauses. A comma alone would create a comma splice."},
  {id:"rw10",skill:"Form, Structure, and Sense",domain:"Standard English Conventions",passage:"The student research team has ______ its results with the library's science club.",prompt:"Which choice completes the text so that it conforms to standard English?",options:["share","sharing","shared","shares"],answer:2,explanation:"The present-perfect construction “has” takes the past participle “shared.”"},
  {id:"rw11",skill:"Words in Context",domain:"Craft and Structure",passage:"The architect's sketch was deliberately sparse, showing only the building's outline and the placement of its windows.",prompt:"As used in the text, “sparse” most nearly means",options:["detailed","unusual","simple","colorful"],answer:2,explanation:"The sketch includes only a few essential features, so “simple” best matches sparse in context."},
  {id:"rw12",skill:"Central Ideas and Details",domain:"Information and Ideas",passage:"A team tested three paper airplane designs by launching each one ten times from the same line. They recorded distance rather than choosing the longest single flight, because one unusual throw could distort the comparison.",prompt:"Why did the team record multiple flights for each design?",options:["To make the test take longer","To reduce the influence of an unusual result","To ensure every plane had identical folds","To avoid measuring distance"],answer:1,explanation:"Repeating trials helps keep one unusually long or short throw from determining the comparison."}
 ],
 math:[
  {id:"m1",skill:"Algebra",domain:"Algebra",passage:"",prompt:"A club orders 4 notebooks and 3 pens for $18. A notebook costs $3. How much does one pen cost?",options:["$2","$3","$4","$6"],answer:0,explanation:"Four notebooks cost 4 × $3 = $12. The pens cost $18 − $12 = $6 total. Divide by 3 pens: $6 ÷ 3 = $2."},
  {id:"m2",skill:"Problem-Solving and Data Analysis",domain:"Problem-Solving and Data Analysis",passage:"",prompt:"A student reads 18 pages in 30 minutes at a steady rate. At that rate, how many pages will the student read in 50 minutes?",options:["24","27","30","36"],answer:2,explanation:"The rate is 18 ÷ 30 = 0.6 page per minute. In 50 minutes: 0.6 × 50 = 30 pages."},
  {id:"m3",skill:"Geometry and Trigonometry",domain:"Geometry and Trigonometry",passage:"",prompt:"A rectangular poster is 8 inches wide and 11 inches tall. A border of equal width is added inside all four edges. If the border is 1 inch wide, what is the area of the remaining inner rectangle, in square inches?",options:["42","48","54","70"],answer:2,explanation:"The border reduces each dimension by 2 inches: the inner rectangle is 6 by 9. Its area is 6 × 9 = 54. Correct answer choice: C."},
  {id:"m4",skill:"Algebra",domain:"Algebra",passage:"",prompt:"If 5x − 7 = 28, what is the value of x?",options:["5","6","7","9"],answer:2,explanation:"Add 7 to both sides to get 5x = 35, then divide by 5: x = 7."},
  {id:"m5",skill:"Advanced Math",domain:"Advanced Math",passage:"",prompt:"The function f is defined by f(x) = 2x² − 3. What is f(4)?",options:["13","21","29","35"],answer:2,explanation:"Substitute 4: 2(4²) − 3 = 2(16) − 3 = 29."},
  {id:"m6",skill:"Problem-Solving and Data Analysis",domain:"Problem-Solving and Data Analysis",passage:"",prompt:"A water bottle contains 750 milliliters. A student drinks 40% of it. How many milliliters remain?",options:["300","450","500","710"],answer:1,explanation:"If 40% was consumed, 60% remains. 0.60 × 750 = 450 milliliters."},
  {id:"m7",skill:"Advanced Math",domain:"Advanced Math",passage:"",prompt:"A quadratic function is f(x) = (x − 2)(x + 5). What are its zeros?",options:["−5 and 2","−2 and 5","−5 and −2","2 and 5"],answer:0,explanation:"Set each factor equal to zero: x − 2 = 0 gives 2, and x + 5 = 0 gives −5."},
  {id:"m8",skill:"Algebra",domain:"Algebra",passage:"",prompt:"A gym charges a $12 sign-up fee plus $8 per class. Which equation gives the total cost C for x classes?",options:["C = 12x + 8","C = 8x + 12","C = 20x","C = 8(x + 12)"],answer:1,explanation:"The fixed $12 fee is added once, and each of x classes costs $8, so C = 8x + 12."},
  {id:"m9",skill:"Problem-Solving and Data Analysis",domain:"Problem-Solving and Data Analysis",passage:"",prompt:"The numbers 6, 8, 10, 10, and 16 are recorded. What is their mean?",options:["8","9","10","11"],answer:2,explanation:"Their sum is 50. Divide by 5 values: the mean is 10."},
  {id:"m10",skill:"Geometry and Trigonometry",domain:"Geometry and Trigonometry",passage:"",prompt:"A circle has radius 3. What is its area?",options:["6π","9π","12π","18π"],answer:1,explanation:"The area formula is A = πr². With r = 3, A = 9π."},
  {id:"m11",skill:"Advanced Math",domain:"Advanced Math",passage:"",prompt:"If 3ˣ = 81, what is x?",options:["3","4","27","78"],answer:1,explanation:"Since 81 = 3⁴, the equation 3ˣ = 3⁴ gives x = 4."},
  {id:"m12",skill:"Geometry and Trigonometry",domain:"Geometry and Trigonometry",passage:"",prompt:"A right triangle has legs of length 6 and 8. What is the length of its hypotenuse?",options:["9","10","12","14"],answer:1,explanation:"By the Pythagorean theorem, c² = 6² + 8² = 100, so c = 10."}
 ]
};
const accountStorageKey=(kind)=>`launchpad:${kind}:${window.launchpadUserId||"local-preview"}`;
const safeRead=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key)??JSON.stringify(fallback))}catch{return fallback}};
const shuffled=(list)=>{const copy=[...list];for(let i=copy.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]]}return copy};
const validViews=["home","opportunities","projects","research","credentials","study","sat"];
const requestedView=location.hash.slice(1);
const state={view:validViews.includes(requestedView)?requestedView:"home",category:"all",cost:"all",query:"",beginner:false,saves:new Set(safeRead(accountStorageKey("saves"),[])),statuses:safeRead(accountStorageKey("statuses"),{}),satSubject:"rw",satIndex:0,satSelection:null,satChecked:false,studyText:"",studyItems:[],studyQuizIndex:0,missionDone:false,opportunityOrder:shuffled(opportunities),projectOrder:shuffled(projects),projectOffset:0,credentialCategory:"all",credentialQuery:"",displayName:localStorage.getItem(accountStorageKey("name"))||"",interests:safeRead(accountStorageKey("interests"),[])};
const $=(sel,root=document)=>root.querySelector(sel);const $$=(sel,root=document)=>[...root.querySelectorAll(sel)];
const escapeHtml=(value="")=>String(value).replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[ch]));
const categoryLabels={research:"Research",volunteering:"Volunteering",internship:"Internship",competition:"Competition","club":"Clubs & activities",project:"Project"};
function interestScore(item){const text=[item.title,item.summary,item.category,item.tag,item.skills].join(" ").toLowerCase();const terms={research:["research","science","data","question","study","archive"],technology:["technology","code","web","data","engineering","cloud","robot"],community:["volunteer","community","service","local","help"],arts:["art","writing","media","story","history","audio"],business:["business","leadership","marketing","entrepreneur"],health:["health","wellbeing","medical","biology"],environment:["environment","nature","climate","garden","water"],learning:["learn","teach","study","guide","tutor"]};return state.interests.reduce((score,key)=>score+((terms[key]||[]).some(term=>text.includes(term))?1:0),0)}

function setView(view,{navigate=true,scroll=true}={}){if(!validViews.includes(view))return;state.view=view;$("#app-shell").dataset.view=view;$("#app-shell").dataset.theme=localStorage.getItem(accountStorageKey("theme"))||"light";$$('.view').forEach(el=>el.classList.toggle("active",el.id===`view-${view}`));$$('[data-view]').forEach(el=>el.classList.toggle("active",el.dataset.view===view));const labels={home:"Home",opportunities:"Find opportunities",projects:"Project starters",research:"Independent research",credentials:"Certificates & badges",study:"Study lab",sat:"SAT practice"};$("#crumb-current").textContent=labels[view];if(navigate&&location.hash!==`#${view}`)history.pushState({view},"",`#${view}`);if(scroll)window.scrollTo({top:0,behavior:"smooth"});if(view==="opportunities")renderOpportunities();if(view==="projects")renderProjects();if(view==="research")renderResearch();if(view==="credentials")renderCredentials();if(view==="sat")renderQuestion();}
// Auth loads this module only after it verifies the saved session. Reapply the
// deep link once the authenticated shell is ready so refresh restores the page.
window.addEventListener("launchpad:ready",()=>{const view=location.hash.slice(1);if(validViews.includes(view))setView(view,{navigate:false,scroll:false})});
function updateHomeDate(){const date=new Intl.DateTimeFormat(undefined,{weekday:"long",month:"long",day:"numeric"}).format(new Date());$("#home-date").textContent=date.toUpperCase()}
function applyProfile(){const name=state.displayName.trim();$("#welcome-name").textContent=name?`${name}.`:"future you.";$("#avatar-button").textContent=(name[0]||window.launchpadUserEmail?.[0]||"A").toUpperCase();$("#settings-name").value=name;$("#app-shell").dataset.theme=localStorage.getItem(accountStorageKey("theme"))||"light";$("#theme-toggle").checked=$("#app-shell").dataset.theme==="dark";$("#interest-summary").textContent=state.interests.length?`${state.interests.length} interests saved on this device.`:"Pick a few things you might like.";$$("[data-interest]").forEach(input=>input.checked=state.interests.includes(input.value))}
function showToast(message){const toast=$("#toast");toast.textContent=message;toast.classList.add("show");clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove("show"),2400)}
function saveState(){localStorage.setItem(accountStorageKey("saves"),JSON.stringify([...state.saves]));localStorage.setItem(accountStorageKey("statuses"),JSON.stringify(state.statuses));renderSaved()}
function savedButton(item){return `<button class="save-button ${state.saves.has(item.id)?"saved":""}" data-save="${escapeHtml(item.id)}" aria-label="${state.saves.has(item.id)?"Remove saved item":"Save item"}" aria-pressed="${state.saves.has(item.id)}">${state.saves.has(item.id)?"♥":"♡"}</button>`}
function costType(item){if(item.costType)return item.costType;const cost=(item.cost||"").toLowerCase();if(/no entry fee|free to|free tools/.test(cost))return "free";if(/free/.test(cost)&&!/varies|depends|usually|often/.test(cost))return "free";if(/paid|dues/.test(cost))return "paid";return "varies"}
function renderOpportunityCard(item){const cost=costType(item);return `<article class="opportunity-card"><div class="card-topline"><span class="category-label ${item.category}">${escapeHtml(categoryLabels[item.category])}</span>${savedButton(item)}</div><h3>${escapeHtml(item.title)}</h3><p class="card-summary">${escapeHtml(item.summary)}</p><div class="card-tags"><span class="tag">${escapeHtml(item.format)}</span><span class="tag cost-tag cost-${cost}">${escapeHtml(item.cost)}</span>${item.highSchoolOnly?'<span class="tag beginner">High-school focused</span>':''}${item.beginner?'<span class="tag beginner">Easy to explore</span>':''}</div>${item.aid?`<p class="cost-aid"><strong>Cost support:</strong> ${escapeHtml(item.aid)}</p>`:""}<div class="card-bottom"><span class="verified demo">↗ ${escapeHtml(item.verified||"Provider source · verify current dates")}</span><button class="details-link" data-detail="${escapeHtml(item.id)}">See details →</button></div></article>`}
function renderOpportunities(){const hsOnly=$("#hs-only-toggle").checked;let filtered=state.opportunityOrder.filter(item=>{let matchesCategory=state.category==="all"||item.category===state.category;let query=(state.query||"").trim().toLowerCase();let matchesQuery=!query||[item.title,item.summary,item.category,item.description,item.sourceName,item.cost,item.aid||""].join(" ").toLowerCase().includes(query);let matchesSchool=item.category!=="internship"||!hsOnly||item.highSchoolOnly===true;let matchesCost=state.cost==="all"||costType(item)===state.cost;return matchesCategory&&matchesQuery&&matchesSchool&&matchesCost&&(!state.beginner||item.beginner)});if(state.interests.length)filtered.sort((a,b)=>interestScore(b)-interestScore(a));$("#opportunity-grid").innerHTML=filtered.length?filtered.map(renderOpportunityCard).join():`<div class="empty-results"><div style="font-size:24px;margin-bottom:8px">✿</div><strong>No opportunities match these filters yet.</strong><p>Try another category or cost filter, or turn off the high-school-only filter. We won't fill the gap with undergraduate listings.</p></div>`;$("#result-count").textContent=`${filtered.length} ${filtered.length===1?"starting point":"starting points"} · provider pages, check current dates`;$("#opportunity-nav-count").textContent=opportunities.length}
