async function readStreamLimited(stream,limit=10*1024*1024){const reader=stream.getReader(),chunks=[];let total=0;while(true){const{value,done}=await reader.read();if(done)break;total+=value.length;if(total>limit){await reader.cancel();throw new Error("This document expands beyond the safe 10 MB text extraction limit.")}chunks.push(value)}const output=new Uint8Array(total);let offset=0;for(const chunk of chunks){output.set(chunk,offset);offset+=chunk.length}return output}
async function unzipEntries(file){const bytes=new Uint8Array(await file.arrayBuffer()),view=new DataView(bytes.buffer);let end=-1;for(let i=Math.max(0,bytes.length-65557);i<bytes.length-3;i++)if(view.getUint32(i,true)===0x06054b50)end=i;if(end<0)throw new Error("This file is not a readable Office or EPUB document.");const count=view.getUint16(end+10,true);let offset=view.getUint32(end+16,true);const entries=new Map();for(let i=0;i<count;i++){if(view.getUint32(offset,true)!==0x02014b50)break;const method=view.getUint16(offset+10,true),size=view.getUint32(offset+20,true),nameLen=view.getUint16(offset+28,true),extraLen=view.getUint16(offset+30,true),commentLen=view.getUint16(offset+32,true),local=view.getUint32(offset+42,true),name=new TextDecoder().decode(bytes.slice(offset+46,offset+46+nameLen));const localName=view.getUint16(local+26,true),localExtra=view.getUint16(local+28,true),start=local+30+localName+localExtra;let data=bytes.slice(start,start+size);if(method===8){if(!window.DecompressionStream)throw new Error("This browser cannot unpack this document format.");const stream=new Blob([data]).stream().pipeThrough(new DecompressionStream("deflate-raw"));data=await readStreamLimited(stream)}else if(method!==0)throw new Error("This document uses a compression type this browser cannot read.");entries.set(name,new TextDecoder().decode(data));offset+=46+nameLen+extraLen+commentLen}return entries}
function xmlText(xml,tag){const doc=new DOMParser().parseFromString(xml,"application/xml");if(doc.querySelector("parsererror"))return "";return [...doc.getElementsByTagName(tag)].map(node=>node.textContent||"").join(" ")}
async function extractPdfText(file){const bytes=new Uint8Array(await file.arrayBuffer()),decoder=new TextDecoder("latin1");let source=decoder.decode(bytes),parts=[source];let cursor=0;while((cursor=source.indexOf("stream",cursor))>=0){let start=cursor+6;if(source[start]===String.fromCharCode(13))start++;if(source[start]===String.fromCharCode(10))start++;const end=source.indexOf("endstream",start);if(end<0)break;const before=source.slice(Math.max(0,cursor-150),cursor);if(before.includes("FlateDecode")){try{const compressed=bytes.slice(start,end),stream=new Blob([compressed]).stream().pipeThrough(new DecompressionStream("deflate"));parts.push(decoder.decode(await readStreamLimited(stream)))}catch{}}cursor=end+9}const textOps=[];for(const part of parts){for(const block of part.matchAll(/\bBT\b([\s\S]*?)\bET\b/g)){const tokens=block[1].match(/\((?:\\.|[^\\)])*\)\s*Tj|<[0-9a-f\s]+>\s*Tj|\[(?:[\s\S]*?)\]\s*TJ/g)||[];for(let token of tokens){token=token.replace(/\s*T[Jj]$/," ");const strings=[...token.matchAll(/\(((?:\\.|[^\\)])*)\)|<([0-9a-f\s]+)>/gi)];for(const m of strings){if(m[1]!==undefined)textOps.push(m[1].replace(/\\([()\\])/g,"$1").replace(/\\n/g," ").replace(/\\r/g," ").replace(/\\[0-7]{1,3}/g," "));else{const hex=m[2].replace(/\s/g,"");let value="";for(let i=0;i+1<hex.length;i+=2)value+=String.fromCharCode(parseInt(hex.slice(i,i+2),16));textOps.push(value)}}}}}return textOps.join(" ").replace(/\s+/g," ").trim()}
async function extractPdfTextWithPdfJs(file){
  const pdfjs=await import("./vendor/pdfjs/pdf.min.mjs");
  pdfjs.GlobalWorkerOptions.workerSrc=new URL("./vendor/pdfjs/pdf.worker.min.mjs",location.href).href;
  const task=pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false,useSystemFonts:true,cMapUrl:new URL("./vendor/pdfjs/cmaps/",location.href).href,cMapPacked:true,standardFontDataUrl:new URL("./vendor/pdfjs/standard_fonts/",location.href).href});
  try{
    const pdf=await task.promise,pages=[];
    for(let pageNumber=1;pageNumber<=pdf.numPages;pageNumber++){
      const page=await pdf.getPage(pageNumber),content=await page.getTextContent();
      pages.push(content.items.map(item=>`${item.str||""}${item.hasEOL?"\n":" "}`).join(""));
    }
    await pdf.destroy();
    return pages.join("\n").trim();
  }catch(error){await task.destroy().catch(()=>{});throw error}
}
async function extractStudyFile(file){
  if(file.size>5*1024*1024)throw new Error("That file is over 5 MB. Try a smaller study file.");
  const ext=file.name.toLowerCase().split(".").pop();let text="";
  if(["docx","pptx","xlsx","odt","epub"].includes(ext)){
    const entries=await unzipEntries(file);
    if(ext==="docx")text=xmlText(entries.get("word/document.xml")||"","t");
    if(ext==="pptx")text=[...entries.entries()].filter(([name])=>/^ppt\/slides\/slide\d+\.xml$/.test(name)).sort(([a],[b])=>a.localeCompare(b,undefined,{numeric:true})).map(([,xml])=>xmlText(xml,"t")).join(" ");
    if(ext==="xlsx"){
      const sharedDoc=new DOMParser().parseFromString(entries.get("xl/sharedStrings.xml")||"<sst/>","application/xml");
      const shared=[...sharedDoc.getElementsByTagName("si")].map(item=>[...item.getElementsByTagName("t")].map(node=>node.textContent||"").join(""));
      const sheets=[...entries.entries()].filter(([name])=>/^xl\/worksheets\/sheet\d+\.xml$/.test(name)).sort(([a],[b])=>a.localeCompare(b,undefined,{numeric:true}));
      text=sheets.map(([,xml])=>{const doc=new DOMParser().parseFromString(xml,"application/xml");return [...doc.getElementsByTagName("c")].map(cell=>{const type=cell.getAttribute("t"),value=cell.getElementsByTagName("v")[0]?.textContent||"";if(type==="s")return shared[Number(value)]||"";if(type==="inlineStr")return [...cell.getElementsByTagName("t")].map(node=>node.textContent||"").join("");return value}).join(" ")}).join(" ");
    }
    if(ext==="odt")text=xmlText(entries.get("content.xml")||"","text:p");
    if(ext==="epub")text=[...entries.entries()].filter(([name])=>/\.(xhtml|html|htm)$/i.test(name)).map(([,xml])=>xmlText(xml,"p")).join(" ");
  }else if(ext==="pdf")text=await extractPdfTextWithPdfJs(file);
  else if(["txt","md","csv","json","html","htm","xml","rtf","yaml","yml","log","js","ts","py","java","sql","css"].includes(ext)){
    text=await file.text();
    if(["html","htm"].includes(ext))text=text.replace(/<script\b[\s\S]*?<\/script>|<style\b[\s\S]*?<\/style>/gi," ").replace(/<[^>]*>/g," ");
    if(ext==="xml")text=xmlText(text,"body")||xmlText(text,"p")||text.replace(/<[^>]*>/g," ");
    if(ext==="rtf")text=text.replace(/\\'[0-9a-f]{2}/gi," ").replace(/\\[a-z]+-?\d* ?/gi," ").replace(/[{}]/g," ");
  }else throw new Error("This file type isn’t supported yet. Try PDF, DOCX, PPTX, XLSX, EPUB, ODT, RTF, or a text-based file.");
  text=text.replace(/\u0000/g," ").replace(ext==="pdf"?/[ \t]+/g:/\s+/g," ").replace(/\n\s*\n+/g,"\n").trim();
  if(text.length<30)throw new Error(ext==="pdf"?"We couldn’t extract readable text from this PDF. Scanned pages need OCR; try selecting and copying the text or paste your notes.":"We couldn’t find enough readable text in that file. Try another file or paste the relevant notes.");
  return text;
}
function buildStudyItems(raw){
  const rows=raw.replace(/\r/g,"").split("\n").map(line=>line.trim()).filter(Boolean),pairs=[];let current=null;
  for(const row of rows){
    const match=row.match(/^\s*(?:\d+[.)]\s*)?(.{2,100}?)\s*:\s*(.*)$/);
    if(match&&!/https?:\/\//i.test(row)){if(current)pairs.push(current);current={term:match[1].replace(/^[^\p{L}\p{N}]+/u,"").trim(),definition:match[2].trim()}}
    else if(current&&row.length>2)current.definition+=` ${row}`;
  }
  if(current)pairs.push(current);
  const usable=pairs.filter(pair=>pair.term&&pair.definition.length>5).slice(0,30);
  if(usable.length>=2)return usable.map((pair,i)=>({id:`local-${i}`,prompt:`What is ${pair.term}?`,answer:pair.definition,explanation:"This answer is taken from the definition in your document. Review it for accuracy."}));
  let sentences=raw.split(/(?<=[.!?])\s+/).map(s=>s.trim()).filter(s=>s.length>28).slice(0,8);if(!sentences.length)sentences=[raw];
  return sentences.slice(0,6).map((sentence,i)=>({id:`local-${i}`,prompt:"What is one key idea from this note?",answer:sentence,explanation:"This answer comes directly from the text you provided. Review it and edit if you want a shorter card."}));
}
function setStudyText(text){state.studyText=text.slice(0,5000);$("#notes-input").value=state.studyText;$("#character-count").textContent=`${state.studyText.length.toLocaleString()} / 5,000`;$("#make-cards").disabled=state.studyText.trim().length<30;$("#study-message").textContent=state.studyText.length>=5000?"Showing the first 5,000 characters.":""}
function makeStudySet(){let raw=state.studyText.trim();if(raw.length<30){$("#study-message").textContent="Add a little more text so there's enough to make a useful set.";return}state.studyItems=buildStudyItems(raw);$("#study-results").classList.remove("hidden");$("#study-set-title").textContent="A few ideas to review";$("#flashcard-total").textContent=state.studyItems.length;$("#quiz-total").textContent=Math.max(1,state.studyItems.length);renderStudyCards();renderStudyQuiz();$("#study-results").scrollIntoView({behavior:"smooth",block:"start"});$("#study-message").textContent="Done — take a look and edit anything that needs a tune-up."}
function renderStudyCards(){$("#flashcard-area").innerHTML=`<div class="flashcard-list">${state.studyItems.map((item,i)=>`<article class="flashcard"><span class="card-label">CARD ${String(i+1).padStart(2,"0")} · FROM YOUR NOTES</span><p contenteditable="true" role="textbox" aria-label="Edit flashcard prompt" data-edit="prompt" data-item="${i}">${escapeHtml(item.prompt)}</p><p class="answer" contenteditable="true" role="textbox" aria-label="Edit flashcard answer" data-edit="answer" data-item="${i}">${escapeHtml(item.answer)}</p></article>`).join("")}</div><p class="source-footnote">Local demo: simple sentence-based prompts, not AI-generated. Your text has not been uploaded.</p>`}
function renderStudyQuiz(){let current=state.studyItems[0];if(!current){$("#quiz-area").innerHTML="";return}let distractors=state.studyItems.filter(i=>i.id!==current.id).slice(0,3);let options=[current.answer,...distractors.map(i=>i.answer)].slice(0,4).sort((a,b)=>a.localeCompare(b));$("#quiz-area").innerHTML=`<div class="quiz-question"><div class="question-domain">QUICK CHECK</div><h3>${escapeHtml(current.prompt)}</h3>${options.map((o,i)=>`<label class="quiz-option"><input type="radio" name="study-quiz" value="${escapeHtml(o)}" /><span>${String.fromCharCode(65+i)}.</span> ${escapeHtml(o)}</label>`).join("")}<div class="study-quiz-submit"><button class="button button-dark" id="check-study-answer">Check answer <span>→</span></button><span class="answer-feedback" id="study-quiz-feedback" aria-live="polite"></span></div></div>`}
