function renderQuestion(){if(!$("#skill-select").options.length)fillSkills();let questions=getSessionQuestions();let q=questions[state.satIndex%questions.length];if(!q){$("#question-area").innerHTML=`<div class="empty-results">No original practice questions are available for this filter yet.</div>`;return}$("#question-step").textContent=`Question ${(state.satIndex%questions.length)+1} of ${questions.length}`;$("#progress-fill").style.width=`${((state.satIndex%questions.length)+1)/questions.length*100}%`;$("#question-area").innerHTML=`${q.passage?`<div class="question-passage">${escapeHtml(q.passage)}</div>`:""}<div class="question-domain">${escapeHtml(q.domain)} · ${escapeHtml(q.skill)}</div><p class="question-prompt">${escapeHtml(q.prompt)}</p><div class="answer-options">${q.options.map((o,i)=>`<button class="answer-option ${state.satChecked&&i===q.answer?"correct":""} ${state.satChecked&&state.satSelection===i&&i!==q.answer?"incorrect":""} ${state.satSelection===i?"selected":""}" data-answer="${i}" ${state.satChecked?"disabled":""}><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${escapeHtml(o)}</span></button>`).join("")}</div><div class="question-actions"><span class="answer-feedback ${state.satChecked?(state.satSelection===q.answer?"correct-text":"wrong"):""}" aria-live="polite">${state.satChecked?(state.satSelection===q.answer?`Nice work. ${escapeHtml(q.explanation)}`:`Not quite. ${escapeHtml(q.explanation)}`):"Choose an answer to check your thinking."}</span><button class="button button-dark" id="sat-action" ${state.satSelection===null&&!state.satChecked?"disabled":""}>${state.satChecked?"Next question":"Check answer"} <span>→</span></button></div>`}
function changeSubject(subject){state.satSubject=subject;state.satIndex=0;state.satSelection=null;state.satChecked=false;$$('.subject-tab').forEach(b=>{b.classList.toggle("active",b.dataset.subject===subject);b.setAttribute("aria-selected",b.dataset.subject===subject)});fillSkills();renderQuestion()}

document.addEventListener("click",e=>{const nav=e.target.closest("[data-view]");if(nav){setView(nav.dataset.view);return}const go=e.target.closest("[data-go]");if(go){setView(go.dataset.go);return}const save=e.target.closest("[data-save]");if(save){e.preventDefault();toggleSave(save.dataset.save);if($("#detail-modal").open)showDetail(save.dataset.save);return}const detail=e.target.closest("[data-detail]");if(detail){showDetail(detail.dataset.detail);return}const project=e.target.closest("[data-project]");if(project){showProject(project.dataset.project);return}const ans=e.target.closest("[data-answer]");if(ans&&!state.satChecked){state.satSelection=Number(ans.dataset.answer);renderQuestion();return}if(e.target.closest("#sat-action")){if(!state.satChecked){if(state.satSelection===null)return;state.satChecked=true}else{state.satIndex++;state.satSelection=null;state.satChecked=false}renderQuestion();return}if(e.target.closest("#check-study-answer")){const selected=$("input[name=study-quiz]:checked");const feedback=$("#study-quiz-feedback");if(!selected){feedback.textContent="Pick an answer first.";return}feedback.textContent=selected.value===state.studyItems[0].answer?"That's it — this sentence is in your notes.":"Not quite. Check the sentence in your notes and try again.";feedback.className=`answer-feedback ${selected.value===state.studyItems[0].answer?"correct-text":"wrong"}`;return}if(e.target.closest("#privacy-button")||e.target.closest("#avatar-button")){ $("#privacy-modal").showModal();return}if(e.target.closest("#clear-local-data")){localStorage.removeItem(accountStorageKey("saves"));localStorage.removeItem(accountStorageKey("statuses"));state.saves.clear();state.statuses={};saveState();$("#privacy-modal").close();showToast("Local saved data cleared.");return}if(e.target.closest("#skip-mission")){ $(".mission-card").classList.add("hidden");return}if(e.target.closest(".notice-close")){e.target.closest(".notice-banner").remove();return}if(e.target.closest("#clear-study")){state.studyText="";state.studyItems=[];setStudyText("");$("#study-results").classList.add("hidden");$("#file-input").value="";return}const tab=e.target.closest("[data-set]");if(tab){$$('.set-tab').forEach(x=>x.classList.toggle("active",x===tab));$("#flashcard-area").classList.toggle("hidden",tab.dataset.set!=="cards");$("#quiz-area").classList.toggle("hidden",tab.dataset.set!=="quiz");return}const done=e.target.closest("[data-project-done]");if(done){done.textContent="Nice — you made a start ✦";done.disabled=true;done.classList.add("mission-done");showToast("One small step counts.");return}});

$("#search-input").addEventListener("input",e=>{state.query=e.target.value;renderOpportunities()});
$("#shuffle-opportunities").addEventListener("click",()=>{state.opportunityOrder=shuffled(opportunities);renderOpportunities();showToast("Fresh mix from our curated directory. Source dates still need checking.")});
$("#hs-only-toggle").addEventListener("change",renderOpportunities);
$(".cost-filter-row").addEventListener("click",e=>{const b=e.target.closest("[data-cost]");if(!b)return;state.cost=b.dataset.cost;$$('[data-cost]').forEach(x=>{const selected=x===b;x.classList.toggle("selected",selected);x.setAttribute("aria-pressed",String(selected))});renderOpportunities()});
$("#shuffle-projects").addEventListener("click",()=>{state.projectOffset+=4;if(state.projectOffset>=projects.length){state.projectOffset=0;state.projectOrder=shuffled(projects)}renderProjects();showToast("Here are some different starter ideas.")});
$("#credential-search").addEventListener("input",e=>{state.credentialQuery=e.target.value;renderCredentials()});
$("#credential-filters").addEventListener("click",e=>{const chip=e.target.closest("[data-credential]");if(!chip)return;state.credentialCategory=chip.dataset.credential;$$('[data-credential]').forEach(x=>x.classList.toggle("selected",x===chip));renderCredentials()});
$("#settings-name").addEventListener("input",e=>{if(e.target.value.length>40)e.target.value=e.target.value.slice(0,40)});
$("#theme-toggle").addEventListener("change",e=>{const theme=e.target.checked?"dark":"light";localStorage.setItem(accountStorageKey("theme"),theme);$("#app-shell").dataset.theme=theme});
$("#save-display-name").addEventListener("click",()=>{state.displayName=$("#settings-name").value.trim().slice(0,40);localStorage.setItem(accountStorageKey("name"),state.displayName);applyProfile();showToast(state.displayName?"Your display name is saved on this device.":"Display name cleared.")});
$("#retake-interests").addEventListener("click",()=>{$("#interest-modal").showModal()});
$("#save-interests").addEventListener("click",()=>{state.interests=$$('[data-interest]:checked').map(x=>x.value);localStorage.setItem(accountStorageKey("interests"),JSON.stringify(state.interests));state.projectOrder=shuffled(projects).sort((a,b)=>interestScore(b)-interestScore(a));state.projectOffset=0;applyProfile();renderOpportunities();renderProjects();$("#interest-modal").close();showToast("Your interests are updated.")});
$("#avatar-button").addEventListener("click",applyProfile);$("#privacy-button").addEventListener("click",applyProfile);
$("#clear-local-data").addEventListener("click",()=>{for(const key of ["name","interests","theme"])localStorage.removeItem(accountStorageKey(key));state.displayName="";state.interests=[];$("#app-shell").dataset.theme="light";applyProfile()});
document.addEventListener("click",e=>{const idea=e.target.closest("[data-research]");if(idea)showResearch(idea.dataset.research)});
$("#category-filters").addEventListener("click",e=>{const b=e.target.closest("[data-category]");if(!b)return;state.category=b.dataset.category;$$('[data-category]').forEach(x=>x.classList.toggle("selected",x===b));renderOpportunities()});
$("#beginner-toggle").addEventListener("click",e=>{state.beginner=!state.beginner;e.currentTarget.setAttribute("aria-pressed",state.beginner);renderOpportunities()});
document.addEventListener("change",e=>{if(!e.target.matches("[data-status]"))return;state.statuses[e.target.dataset.status]=e.target.value;saveState();showToast("Your private status was updated.")});
document.addEventListener("input",e=>{if(!e.target.matches("[data-edit]"))return;const item=state.studyItems[Number(e.target.dataset.item)];if(item)item[e.target.dataset.edit]=e.target.textContent.trim()});
$("#notes-input").addEventListener("input",e=>setStudyText(e.target.value));
async function loadStudyFile(file){try{$("#study-message").textContent=`Reading ${file.name} locally…`;const text=await extractStudyFile(file);setStudyText(text);$("#study-message").textContent=`Text extracted from ${file.name}. It stayed in this browser; review it before making a study set.`}catch(error){$("#study-message").textContent=error.message||"We couldn’t read that file. Try another format or paste the text."}}
$("#file-input").addEventListener("change",async e=>{const file=e.target.files[0];if(file)await loadStudyFile(file)});
$("#dropzone").addEventListener("dragover",e=>{e.preventDefault();e.currentTarget.classList.add("dragover")});$("#dropzone").addEventListener("dragleave",e=>e.currentTarget.classList.remove("dragover"));$("#dropzone").addEventListener("drop",async e=>{e.preventDefault();e.currentTarget.classList.remove("dragover");const file=e.dataTransfer.files[0];if(file)await loadStudyFile(file)});
$("#make-cards").addEventListener("click",makeStudySet);$("#skill-select").addEventListener("change",()=>{state.satIndex=0;state.satSelection=null;state.satChecked=false;renderQuestion()});$$('.subject-tab').forEach(b=>b.addEventListener("click",()=>changeSubject(b.dataset.subject)));
renderOpportunities();renderProjects();renderResearch();renderCredentials();renderSaved();fillSkills();renderQuestion();updateHomeDate();applyProfile();setView(state.view,{navigate:false,scroll:false});window.addEventListener("popstate",()=>{const view=location.hash.slice(1);if(validViews.includes(view))setView(view,{navigate:false,scroll:false})});setInterval(updateHomeDate,60*60*1000);
